import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// One row per frame type, so a new frame is a row here rather than another case on the dispatch.
// A Map, not a record: the wire's snake_case stays a string literal, which camelcase never reads as an identifier.
const validators = new Map<string, (message: Record<string, unknown>) => ValidationResult>([
  ['user_message', validateUserMessage],
  ['ping', validatePingMessage],
  ['list_sessions', validateListSessionsMessage],
]);

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators.get(message.type);
  if (!validate) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }
  return validate(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// A non-negative integer is the only shape a page limit answers.
const isNonNegativeInteger = (value: unknown): boolean =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0;

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && !isNonNegativeInteger(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  const invalid = invalidCursor(message.before);
  if (invalid) return {valid: false, error: invalid};
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: message.limit as number | undefined,
      before: message.before as ListSessionsMessage['before'],
    },
  };
}

// Each refusal names its field, so a client can tell which half of the cursor was refused.
function invalidCursor(before: unknown): string | undefined {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
    return 'list_sessions before must be an object with sessionId and updatedAt';
  }
  const cursor = before as Record<string, unknown>;
  const {sessionId, updatedAt} = cursor;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return 'list_sessions before.sessionId must be a string of 1 to 128 characters';
  }
  if (!parsesAsDate(updatedAt)) {
    return 'list_sessions before.updatedAt must parse as a date';
  }
  return undefined;
}

// A wire time is an ISO string or a finite epoch number, so a row that went through JSON still pages.
const parsesAsDate = (value: unknown): boolean => isDateString(value) || isEpochTime(value);
const isDateString = (value: unknown): boolean => typeof value === 'string' && !Number.isNaN(Date.parse(value));
const isEpochTime = (value: unknown): boolean => typeof value === 'number' && Number.isFinite(value);

